def max_len_sub(arr, n):
    # Initialize a list to store the maximum length of subsequence ending at each index
    dp = [1] * n

    # Iterate through the array starting from the second element
    for i in range(1, n):
        # Check all previous elements to find the longest subsequence that can be extended by arr[i]
        for j in range(i):
            if abs(arr[i] - arr[j]) <= n:
                dp[i] = max(dp[i], dp[j] + 1)

    # The maximum value in dp will be the length of the longest subsequence
    return max(dp)
```

